const getOrganizationSlug=()=>{const n=window.location.hostname;return n.includes("bogdanauto.com.ua")||n.includes("localhost")?"default":n.includes("hyundai-zp")?"hyundai-zp":n.includes("hyundai-ck")?"hyundai-ck":n.includes("hyundai-kyiv")?"hyundai-kyiv":n.includes("hyundai-volyn")?"hyundai-volyn":n.includes("hyundai-if")?"hyundai-if":n.includes("hyundai-cn")?"hyundai-cn":n.includes("kr-bogdanauto.hyundai")?"kr-bogdanauto.hyundai":"default"};export{getOrganizationSlug};